-- Reference relational schema. Runtime generator exports CSVs; this DDL documents keys and relationships.
CREATE TABLE Customer (customer_id VARCHAR PRIMARY KEY, signup_date DATE NOT NULL, segment VARCHAR NOT NULL, region VARCHAR NOT NULL, acquisition_channel VARCHAR NOT NULL, seasonal_user BOOLEAN NOT NULL);
CREATE TABLE Subscription (subscription_id VARCHAR PRIMARY KEY, customer_id VARCHAR NOT NULL REFERENCES Customer(customer_id), plan VARCHAR NOT NULL, monthly_price DECIMAL(12,2) NOT NULL CHECK(monthly_price >= 0), start_date DATE NOT NULL, status VARCHAR NOT NULL CHECK(status IN ('active','churned')), end_date DATE, churn_type VARCHAR NOT NULL CHECK(churn_type IN ('none','voluntary','involuntary')), CHECK(end_date IS NULL OR end_date >= start_date));
CREATE TABLE UsageSnapshot (snapshot_id VARCHAR PRIMARY KEY, subscription_id VARCHAR NOT NULL REFERENCES Subscription(subscription_id), customer_id VARCHAR NOT NULL REFERENCES Customer(customer_id), snapshot_month DATE NOT NULL, usage_units DECIMAL(14,3) NOT NULL CHECK(usage_units >= 0), active_days INTEGER NOT NULL CHECK(active_days BETWEEN 0 AND 31), feature_window_end DATE NOT NULL, UNIQUE(subscription_id,snapshot_month));
CREATE TABLE BillingEvent (billing_event_id VARCHAR PRIMARY KEY, customer_id VARCHAR NOT NULL REFERENCES Customer(customer_id), subscription_id VARCHAR NOT NULL REFERENCES Subscription(subscription_id), event_date DATE NOT NULL, event_type VARCHAR NOT NULL, amount DECIMAL(12,2) NOT NULL, payment_status VARCHAR NOT NULL CHECK(payment_status IN ('paid','late','failed','refunded','pending')), currency CHAR(3) NOT NULL);
CREATE TABLE SupportCase (support_case_id VARCHAR PRIMARY KEY, customer_id VARCHAR NOT NULL REFERENCES Customer(customer_id), subscription_id VARCHAR NOT NULL REFERENCES Subscription(subscription_id), created_at DATE NOT NULL, category VARCHAR NOT NULL, severity VARCHAR NOT NULL CHECK(severity IN ('low','medium','high')), status VARCHAR NOT NULL CHECK(status IN ('open','resolved')));
CREATE TABLE Offer (offer_id VARCHAR PRIMARY KEY, offer_name VARCHAR NOT NULL, discount_rate DECIMAL(5,4) NOT NULL CHECK(discount_rate BETWEEN 0 AND 1), max_cost DECIMAL(12,2) NOT NULL CHECK(max_cost >= 0), min_margin_rate DECIMAL(5,4) NOT NULL CHECK(min_margin_rate BETWEEN 0 AND 1), start_date DATE NOT NULL, end_date DATE NOT NULL, active BOOLEAN NOT NULL, CHECK(end_date >= start_date));
CREATE TABLE EligibilityRule (eligibility_rule_id VARCHAR PRIMARY KEY, offer_id VARCHAR NOT NULL REFERENCES Offer(offer_id), min_risk DECIMAL(5,4) NOT NULL CHECK(min_risk BETWEEN 0 AND 1), allowed_plans VARCHAR NOT NULL, require_active BOOLEAN NOT NULL, max_offer_cost DECIMAL(12,2) NOT NULL CHECK(max_offer_cost >= 0), effective_from DATE NOT NULL, effective_to DATE NOT NULL, CHECK(effective_to >= effective_from));
CREATE TABLE CampaignContact (campaign_contact_id VARCHAR PRIMARY KEY, customer_id VARCHAR NOT NULL REFERENCES Customer(customer_id), subscription_id VARCHAR NOT NULL REFERENCES Subscription(subscription_id), offer_id VARCHAR NOT NULL REFERENCES Offer(offer_id), prediction_date DATE NOT NULL, assigned_group VARCHAR NOT NULL CHECK(assigned_group IN ('treatment','control')), offer_sent BOOLEAN NOT NULL, offer_cost DECIMAL(12,2) NOT NULL CHECK(offer_cost >= 0), eligibility_status VARCHAR NOT NULL CHECK(eligibility_status IN ('eligible','ineligible')), eligibility_reason VARCHAR NOT NULL, assignment_seed BIGINT NOT NULL);
CREATE TABLE ChurnOutcome (churn_outcome_id VARCHAR PRIMARY KEY, customer_id VARCHAR NOT NULL REFERENCES Customer(customer_id), subscription_id VARCHAR NOT NULL REFERENCES Subscription(subscription_id), prediction_date DATE NOT NULL, churn_date DATE, churned_within_horizon BOOLEAN NOT NULL, churn_type VARCHAR NOT NULL CHECK(churn_type IN ('none','voluntary','involuntary')), label_source VARCHAR NOT NULL);
CREATE TABLE RetentionOutcome (retention_outcome_id VARCHAR PRIMARY KEY, campaign_contact_id VARCHAR NOT NULL REFERENCES CampaignContact(campaign_contact_id), customer_id VARCHAR NOT NULL REFERENCES Customer(customer_id), outcome_date DATE NOT NULL, retained BOOLEAN NOT NULL, attributed_offer_id VARCHAR REFERENCES Offer(offer_id), outcome_source VARCHAR NOT NULL);
-- Lifecycle events are append-only in the exported event tables; do not update historical facts in place.
